function harness(overrides={}){const objects=new Map(),c=context(),calls=[];const io={savePrivate:async(name,value)=>{if(objects.has(name))throw new Error('IMMUTABLE_OBJECT_EXISTS');objects.set(name,value);return {sha256:digest(value),generation:'1'};},loadGatewayToken:()=>{throw new Error('FORBIDDEN_CREDENTIAL');},ibStore:new Proxy({}, {get(){throw new Error('FORBIDDEN_CREDENTIAL');}})};return {objects,c,calls,io,options:{sourceDate:DATE,io,now:NOW,loadContext:async()=>c,readArchive:async()=>archive(),verifyArchive:async({archive:a,expectedAccount,expectedQueryId,sourceDate})=>({status:'archive-verified',rawSha256:digest(a.bytes),account:expectedAccount,configuredQueryId:expectedQueryId,sourceDate,generation:a.metadata.generation}),verifyArchiveFinancial:financialOracle(),expectedAccount:ACCOUNT,expectedQueryId:QUERY,snapshotReader:async({sourceKey})=>{calls.push(sourceKey);return snapshot(sourceKey);},verifySnapshotCompletion:verifySnapshot,...overrides}};}
async function result(overrides={}){const h=harness(overrides),receipt=await runPrivateEodReport(h.options),html=h.objects.get(receipt.artifact.privateObject);return {...h,receipt,html,model:extractNightActionModel(html)};}
