test('official UI cash extract stays private and preserves original range without API/sync/annualised-daily claims',async()=>{
  const ui=uiAdapt(uiFixture());assert.equal(ui.status,'ui-export-observed');assert.equal(ui.uiCash.total,42.35);assert.equal(ui.completion,null);assert.equal(Object.hasOwn(ui,'raw'),false);
  assert.equal(ui.provenance.uiReportStart,'2025-01-01');assert.equal(ui.privateSource.periodReturnsNotDaily,true);assert.equal(ui.privateSource.originalBinaryHashesLocallyVerified,false);assert.equal(ui.privateSource.automaticApiReaderTested,false);
  const {buildEodActionModel}=await import('../../scripts/xuan-ib-eod-action-model.mjs');
  const {classifySleepPublication}=await import('../../scripts/xuan-ib-sleep-priority.mjs');
  const ib=await readVerifiedSnapshot('sharesight.ibGroupedPerformance',{sourceDate:DATE,now:NOW,reader:async()=>snapshot('sharesight.ibGroupedPerformance')});
  for(const capture of [null,live()]){
    const flex=applyFinancialVerification(adapt(archive()),await financialOracle()({archive:archive()}),{expectedAccount:ACCOUNT,expectedQueryId:QUERY,sourceDate:DATE,generation:'1'});
    const sourceOutcomes=[{sourceKey:'ib.flexEod',status:'verified',rawFingerprint:flex.rawFingerprint},...([ib,ui].map(s=>({sourceKey:s.sourceKey,status:s.status,rawFingerprint:s.rawFingerprint}))),{sourceKey:'ib.optionalLive',status:capture?'captured':'not-called',rawFingerprint:capture?digest(capture):null}];
    const model=buildEodActionModel({dataDate:'2026-10-09',sourceDate:DATE,asOfHkt:'2026-10-09 13:00 HKT · 数据至 '+DATE,flex,snapshots:[ib,ui],live:capture,reserve:50,sourceOutcomes});
    assert.equal(model.cash.noah,42.35);assert.equal(model.cash.pool,242.35);assert.equal(model.allocation.status,'ready');assert.equal(model.cash.planning,null);assert.equal(model.cash.executableBudget,null);
    const html=renderNightActionReport(model);assert.ok(html.includes('官方 UI 导出'));assert.ok(html.includes('2025-01-01 至 '+DATE));assert.ok(html.includes('区间收益非单日；仅私有验收'));assert.ok(!html.includes('synthetic.xlsx'));
    assert.throws(()=>classifySleepPublication(html),/private acceptance only/);
    // A fully bound synthetic receipt must still hit the explicit private-only
    // boundary before any publisher request, not fail an earlier hash check.
    const r=await result();const receipt=structuredClone(r.receipt);for(const s of receipt.sources)s.rawFingerprint=model.sourceOutcomes.find(o=>o.sourceKey===s.sourceKey).rawFingerprint;
    model.sourceManifestSha256=digest(receipt.sources.map(s=>({sourceKey:s.sourceKey,privateObject:s.privateObject,generation:s.generation,sha256:s.sha256,rawFingerprint:s.rawFingerprint})).sort((a,b)=>a.sourceKey.localeCompare(b.sourceKey)));
    model.evidenceSha256=digest({sourceOutcomes:model.sourceOutcomes,sourceManifestSha256:model.sourceManifestSha256});
    const bound=renderNightActionReport(model);receipt.sourceOutcomes=model.sourceOutcomes;receipt.sourceManifestSha256=model.sourceManifestSha256;receipt.evidenceSha256=model.evidenceSha256;receipt.artifact.sha256=digest(bound);
    assert.throws(()=>validateEodReceipt(receipt,bound,'2026-10-09',DATE),/UI_EXPORT_PRIVATE_ONLY/);
    let calls=0;await assert.rejects(publishPrepared({html:bound,receipt,now:NOW,loadContext:async()=>r.c,request:async()=>{calls++;}}),/UI_EXPORT_PRIVATE_ONLY/);assert.equal(calls,0);
  }
  const automatic=await result({snapshotReader:async({sourceKey})=>sourceKey==='sharesight.noahPerformance'?ui:snapshot(sourceKey)});
  assert.equal(automatic.model.cash.noah,null);assert.equal(automatic.model.sourceOutcomes[2].status,'missing-fields');
});
