  const candidate={ref:'origin/codex/xuan-ib-synthetic-eod',sha:'d'.repeat(40),htmlBlob:publication.action.htmlBlob,dataDate:'2026-10-09',commitEpoch:3,publication};
  assert.equal(selectNewestCandidate([candidate],meta,richPublication),null);
  const weakMeta={...meta,htmlBlob:publication.action.htmlBlob};const richer={...candidate,htmlBlob:richPublication.action.htmlBlob,publication:richPublication};assert.equal(selectNewestCandidate([richer],weakMeta,publication),richer);
  for(const edit of [c=>delete c.publication.action,c=>c.publication.action.htmlBlob='f'.repeat(40),c=>c.publication.action.schemaVersion=5]){const c=structuredClone(candidate);edit(c);assert.throws(()=>selectNewestCandidate([c],meta,richPublication));}
