test('R3N1 every optional-derived boundary degrades orders while preserving independently valid core cards',async()=>{
  const largeArchive=archive();largeArchive.bytes=largeArchive.bytes.replace('endingCash="200"','endingCash="600000000000"');largeArchive.metadata.rawSha256=digest(largeArchive.bytes);
  // Separate fixed synthetic oracle for this predeclared large-balance archive;
  // it never copies facts or financial metadata from the adapter input.
  const largeProof=await financialOracle()({archive:archive()});largeProof.rawSha256=digest(largeArchive.bytes);
  const largeSnapshot=async({sourceKey})=>{const s=snapshot(sourceKey);if(sourceKey==='sharesight.ibGroupedPerformance')s.raw.data.report.holdings[5].value=600e9;return s;};
  const fractionalSnapshot=async({sourceKey})=>{const s=snapshot(sourceKey);if(sourceKey==='sharesight.ibGroupedPerformance')s.raw.data.report.holdings[3].value=180.004;return s;};
  const projectedOverflow=async({sourceKey})=>{const s=snapshot(sourceKey);if(sourceKey==='sharesight.ibGroupedPerformance')for(const row of s.raw.data.report.holdings.slice(0,5))row.value*=900e6;return s;};
  const filled={...order('BUY'),cum_shares_qty:'2',remaining_shares_qty:'0'};
  const cases=[
    {captureOptionalLive:async()=>live([order('BUY','1000000000000')])},
    {verifyArchiveFinancial:null,captureOptionalLive:async()=>live([order('BUY','1000000000000')])},
    {snapshotReader:fractionalSnapshot,captureOptionalLive:async()=>live([filled])},
    {readArchive:async()=>largeArchive,verifyArchiveFinancial:async()=>structuredClone(largeProof),snapshotReader:largeSnapshot,captureOptionalLive:async()=>live()},
    {snapshotReader:projectedOverflow,captureOptionalLive:async()=>live([order('BUY','20000000000')])},
  ];
  for(const options of cases){
    const base=await result({...options,captureOptionalLive:null}),r=await result(options);
    assert.equal(r.model.orders.status,'unknown');assert.equal(r.model.orders.reason,'ORDERS_MALFORMED_OR_UNMATCHED');assert.equal(r.model.sourceOutcomes[3].status,'malformed');
    for(const key of ['orderReserve','planning','totalCapacity'])assert.equal(r.model.cash[key],null);
    assert.equal(r.model.allocation.projectedTotal,null);assert.equal(r.model.replenishment.status,'unavailable');
    for(const key of ['ib','noah','pool','reserve','callApplied','cashLike','eod'])assert.deepEqual(r.model.cash[key],base.model.cash[key]);
    assert.deepEqual(r.model.allocation,base.model.allocation);assert.deepEqual(r.model.reconciliation,base.model.reconciliation);
    assert.equal(validateNightActionHtml(r.html,'2026-10-09').orderCount,null);
    for(const title of ['本轮补仓','挂单提醒','现金优先补仓参考','股票四类配置'])assert.ok(r.html.includes(title));
  }
});
